    easier: ["ضغطٌ أخفّ ومنطقةٌ أصغر.", "Lighter pressure and a smaller area."],
    harder: ["الذراعُ فوق الرأس أثناء التحريك، فتكون الندبةُ ممدودة.", "With the arm overhead during the mobilisation, so the scar is on stretch."],
    stopIf: ["انفتح الجرحُ أو سال منه شيء، أو احمرارٌ أو حرارة، أو حرقةُ جلد الأشعّة ⟵ توقّفي وأخبري الأخصائيّة أو الطبيب؛ كتلةٌ صلبة جديدة في الندبة أو الصدر ⟵ طبيبُ الأورام عاجلاً (قاعدةُ الانتكاس).", "The wound opens or oozes, redness or heat, or burning of the radiation skin → stop and tell the specialist or doctor; a new hard lump in the scar or chest → urgent oncology (the recurrence rule)."],
    equipment: ["مرطّبٌ بلا عطر، ومرآة.", "An unscented moisturiser, and a mirror."],
    doseNote: ["خمسُ دقائق مرّةً أو مرّتين في اليوم بعد التئام الجرح (اقتراح — Torres Lacomba 2010).", "Five minutes once or twice a day once the wound has healed (a proposal — Torres Lacomba 2010)."],
    images: [{ key: "lymph-chest-scar-mobilisation-1", ar: "أصابعُ امرأةٍ تحرّك جلدَ ندبةٍ أفقيةٍ ملتئمة بعد استئصال الثدي", en: "A woman's fingers moving the skin of a healed horizontal mastectomy scar", search: "mastectomy scar massage" }],
